<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import * as quizApi from '../api/quiz'
const rows=ref([]); const loading=ref(false); const query=reactive({ mastered:false, page:1, pageSize:30 })
async function load(){loading.value=true;try{const r=await quizApi.listWrongQuestions(query);rows.value=r.data.data?.rows||[]}catch(e){ElMessage.error(e.response?.data?.msg||'错题加载失败')}finally{loading.value=false}}
async function mastered(row){try{await quizApi.updateWrongQuestionMastered(row.id,row.mastered);ElMessage.success('已更新');await load()}catch(e){ElMessage.error(e.response?.data?.msg||'更新失败')}}
async function remove(row){try{await ElMessageBox.confirm('确定删除这条错题记录？','确认删除',{type:'warning'});await quizApi.deleteWrongQuestion(row.id);ElMessage.success('已删除');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.response?.data?.msg||'删除失败')}}
onMounted(load)
</script>
<template><div class="page"><div class="page-heading"><div><h2>错题本</h2><p>重复练习薄弱知识点，掌握后可以归档。</p></div><el-radio-group v-model="query.mastered" @change="load"><el-radio-button :value="false">未掌握</el-radio-button><el-radio-button :value="true">已掌握</el-radio-button></el-radio-group></div><el-card><el-table v-loading="loading" :data="rows" empty-text="暂无错题"><el-table-column prop="topic" label="知识点" width="180"/><el-table-column prop="content" label="题目" min-width="300"><template #default="scope">{{ scope.row.content || `题目 #${scope.row.questionId}` }}</template></el-table-column><el-table-column prop="wrongCount" label="错误次数" width="100"/><el-table-column label="状态" width="100"><template #default="scope"><el-tag :type="scope.row.mastered?'success':'warning'">{{scope.row.mastered?'已掌握':'待复习'}}</el-tag></template></el-table-column><el-table-column label="操作" width="160"><template #default="scope"><el-button link type="primary" @click="scope.row.mastered=false; mastered(scope.row)">{{scope.row.mastered?'取消掌握':'标记掌握'}}</el-button><el-button link type="danger" @click="remove(scope.row)">删除</el-button></template></el-table-column></el-table></el-card></div></template>
<style scoped>.page{max-width:1200px;margin:0 auto}.page-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}h2{margin:0 0 6px}p{color:#909399;margin:0}@media(max-width:600px){.page-heading{align-items:flex-start;flex-direction:column;gap:12px}}</style>
